def calculate_sum(N):
    # Define the sequence y_i where y_{i+1} = sum(y_1 to y_i)
    # We must start with y_1. Let y_1 = 1.
    y = [0] * (N + 2)
    y[1] = 1

    # Calculate y_2 through y_{N+1}
    current_sum = 1
    for i in range(2, N + 2):
        y[i] = current_sum
        current_sum += y[i]

    # Calculate the required sum S = sum_{i=1}^{N} y_i / y_{i+1}
    S = 0
    for i in range(1, N + 1):
        # This involves y_i / y_{i+1}
        S += y[i] / y[i+1]

    return S

N = 2023
result = calculate_sum(N)
